@charset "UTF-8";
body {
  margin: 0px;
}

.log-container {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow-y: auto;
  font-family: system-ui, sans-serif;
  background: var(--appsmith-theme-cardColor, #334155);
  border-radius: var(--appsmith-theme-borderRadius);
  box-shadow: var(--appsmith-theme-boxShadow);
  padding: 20px;
  box-sizing: border-box;
}

/* Centered date header with lines */
.date-separator {
  text-align: center;
  font-weight: 600;
  color: var(--appsmith-theme-textMutedColor, #64748b);
  font-size: 13px;
  margin: 18px 0 8px;
  position: relative;
}

.date-separator::before,
.date-separator::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 40%;
  height: 1px;
  background: var(--appsmith-theme-borderColor, #334155);
}

.date-separator::before {
  left: 0;
}

.date-separator::after {
  right: 0;
}

/* Each log entry */
.log-entry {
  display: flex;
  flex-direction: column;
  padding: 10px 12px;
  border-radius: 6px;
  margin-bottom: 8px;
  transition: background-color 0.2s ease;
}

/* ✅ Hover background */
.log-entry:hover {
  background-color: var(--appsmith-theme-surfaceHoverColor, #26344b);
}

.log-datetime {
  font-size: 12px;
  color: var(--appsmith-theme-textSecondaryColor, #94a3b8);
  line-height: 1.5;
}

.log-user {
  font-weight: 700;
  font-size: 13px;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  line-height: 1.5;
}

.log-message {
  font-size: 13px;
  color: var(--appsmith-theme-textStrongColor, #ffffff);
  line-height: 1.5;
}

/* Theme scrollbars (no bright default bars in dark) */
* {
  scrollbar-color: var(--appsmith-theme-borderColor, #334155) var(--appsmith-theme-surfaceColor, #0f172a);
  scrollbar-width: thin;
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

::-webkit-scrollbar-thumb {
  background: var(--appsmith-theme-borderColor, #334155);
  border-radius: 5px;
}

::-webkit-scrollbar-corner {
  background: var(--appsmith-theme-surfaceColor, #0f172a);
}

.log-message {
  overflow-wrap: anywhere;
  word-break: break-word;
}

